INSERT INTO academy_way_paths
  (slug, position, title, purpose, coverage, namespace_name)
VALUES
  ('biblical-realities', 9, '101 Biblical Realities · KJV', 'Start at 0, then choose a track. All 101 numbered topics have their own lesson and worked check.', 'Nature; art and daily life; dreams and visions; remembrance; questioning and truth; extended KJV studies.', 'tabor-academy-way-biblical-realities-dev'),
  ('kjv-nature', 10, 'Nature, Animals & the Cosmos', 'Compare the roles of created things, materials, animals, and images.', 'Record where each detail appears and what it does in that passage.', 'tabor-academy-way-kjv-nature-dev'),
  ('kjv-body', 11, 'Body, Art, Music & Celebration', 'Compare narrated actions, poetry, worship, and specific instructions.', 'Use the words and context to identify when a practice is described, celebrated, or restricted.', 'tabor-academy-way-kjv-body-dev'),
  ('kjv-dreams', 12, 'Dreams, Visions & Spiritual Perception', 'Trace speakers, experiences, and the limits of what each account reports.', 'Use reading, role cards, and diagrams to compare accounts.', 'tabor-academy-way-kjv-dreams-dev'),
  ('kjv-remembrance', 13, 'Remembrance, Ancestors & Death', 'Read genealogies, memorials, death accounts and oral retellings.', 'Trace who preserves the record, what survives, and whose name or act is remembered.', 'tabor-academy-way-kjv-remembrance-dev'),
  ('kjv-mind', 14, 'Mind, Questioning, Freedom & Truth', 'Check a claim about authority, mercy, truth, or conduct against the passage.', 'Use verses and context to distinguish a teaching from the example you build from it.', 'tabor-academy-way-kjv-mind-dev'),
  ('kjv-expansion', 15, 'KJV Expansion · Truth, Evidence & Practice', 'Carry the same reading and verification process into additional KJV passages.', 'Plain speech, conflicting records, witness, discernment, Isaiah, teaching, and care.', 'tabor-academy-way-kjv-expansion-dev')
INSERT INTO academy_way_missions
  (slug, path, position, title, outcome, build, flip, integrate, verify, link)
VALUES
  ('biblical-realities-zero', 'biblical-realities', 100, '0 · Begin with the passage', 'Save one evidence card you can check again: topic, exact KJV line, speaker, setting, what it supports, and what is still open.', '1+1=2. Open one numbered lesson. Use the King James Version and locate its anchor verse. Read the surrounding paragraph. The source edition is the eBible King James (Authorized) Version, ENGKJV.', '1−1=0. Clear the label long enough to read the words. Note who speaks, to whom, and whether the passage is a story, poem, command, or question. Identify any word used in the heading that the passage does not use.', '1×1=1. Do the short exercise, preserve the exact line, and write your reading next to it. Use a companion lesson to test a similar claim in a new context.', '1÷1=1. Compare your work with the worked check. Name what changed when you read the context. Keep an open question for a later reading.', 'way/kjv-nature/'),
  ('biblical-realities-track-1', 'biblical-realities', 101, 'Nature, Animals & the Cosmos · 1–20', 'Compare the roles of created things, materials, animals, and images.', 'Choose one numbered module between 1 and 20. Write down its title and KJV references.', 'Identify the genre and record the difference between the title, the exact wording, and your first impression.', 'Record where each detail appears and what it does in that passage.', 'Use the worked check in your chosen module. Ask a second reader to point to the same line.', 'way/kjv-nature/'),
  ('biblical-realities-track-2', 'biblical-realities', 102, 'Body, Art, Music & Celebration · 21–40', 'Compare narrated actions, poetry, worship, and specific instructions.', 'Choose one numbered module between 21 and 40. Write down its title and KJV references.', 'Identify the genre and record the difference between the title, the exact wording, and your first impression.', 'Use the words and context to identify when a practice is described, celebrated, or restricted.', 'Use the worked check in your chosen module. Ask a second reader to point to the same line.', 'way/kjv-body/'),
  ('biblical-realities-track-3', 'biblical-realities', 103, 'Dreams, Visions & Spiritual Perception · 41–60', 'Trace speakers, experiences, and the limits of what each account reports.', 'Choose one numbered module between 41 and 60. Write down its title and KJV references.', 'Identify the genre and record the difference between the title, the exact wording, and your first impression.', 'Use reading, role cards, and diagrams to compare accounts.', 'Use the worked check in your chosen module. Ask a second reader to point to the same line.', 'way/kjv-dreams/'),
  ('biblical-realities-track-4', 'biblical-realities', 104, 'Remembrance, Ancestors & Death · 61–75', 'Read genealogies, memorials, death accounts and oral retellings.', 'Choose one numbered module between 61 and 75. Write down its title and KJV references.', 'Identify the genre and record the difference between the title, the exact wording, and your first impression.', 'Trace who preserves the record, what survives, and whose name or act is remembered.', 'Use the worked check in your chosen module. Ask a second reader to point to the same line.', 'way/kjv-remembrance/'),
  ('biblical-realities-track-5', 'biblical-realities', 105, 'Mind, Questioning, Freedom & Truth · 76–101', 'Check a claim about authority, mercy, truth, or conduct against the passage.', 'Choose one numbered module between 76 and 101. Write down its title and KJV references.', 'Identify the genre and record the difference between the title, the exact wording, and your first impression.', 'Use verses and context to distinguish a teaching from the example you build from it.', 'Use the worked check in your chosen module. Ask a second reader to point to the same line.', 'way/kjv-mind/'),
  ('biblical-realities-more', 'biblical-realities', 106, 'Continue into the KJV expansion', 'Follow a verified source line into one new topic and connect it to a previous lesson.', 'Choose a lesson on a witness, a competing claim, a command, or an image. Copy its central KJV line.', 'Mark the difference between what the text says, what you infer, and what would need another source.', 'Follow the related lesson to the Academy language, life, or humanities path. Bring one finding back to the original question.', 'A second reader should be able to reproduce your conclusion from the recorded references.', 'way/kjv-expansion/')
INSERT INTO academy_way_missions
  (slug, path, position, title, outcome, build, flip, integrate, verify, link)
VALUES
  ('biblical-reality-001', 'kjv-nature', 107, '1. Stargazing & Constellations', 'Make an evidence card for Stargazing & Constellations. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Genesis 1:14; Job 38:31–32. Anchor verse (Genesis 1:14): “¶ And God said, Let there be lights in the firmament of the heaven to divide the day from the night; and let them be for signs, and for seasons, and for days, and years:” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Make two columns. Put the jobs of the lights in Genesis in one and the star groups named in Job in the other. Mark the difference between observing the sky and making a prediction from it.', 'Worked check — Genesis assigns the lights seasons and timekeeping; Job names star groups in questions about God''s power. Neither passage supplies a horoscope. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-nature/biblical-reality-002/'),
  ('biblical-reality-002', 'kjv-nature', 108, '2. The Moon & Lunar Cycles', 'Make an evidence card for The Moon & Lunar Cycles. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Psalm 104:19; Psalm 81:3. Anchor verse (Psalm 104:19): “He appointed the moon for seasons: the sun knoweth his going down.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Draw a sample lunar month. Label the time marker Psalm 104 names, then check where Psalm 81:3 connects a moon marker and a feast.', 'Worked check — Psalm 104:19 assigns the moon to seasons. The festival language belongs to the separate Psalm 81 passage. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-nature/biblical-reality-003/'),
  ('biblical-reality-003', 'kjv-nature', 109, '3. Snakes & Serpents (as Wisdom)', 'Make an evidence card for Snakes & Serpents (as Wisdom). Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Numbers 21:8–9. Anchor verse (Numbers 21:8): “And the LORD said unto Moses, Make thee a fiery serpent, and set it upon a pole: and it shall come to pass, that every one that is bitten, when he looketh upon it, shall live.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Make two cards headed Comparison and Narrative. Put the serpent language from Matthew and the brass serpent from Numbers on their respective cards.', 'Worked check — Matthew tells the disciples to be wise as serpents and harmless as doves. Numbers narrates a particular sign in the wilderness; it gives no general serpent-handling instruction. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-nature/biblical-reality-004/'),
  ('biblical-reality-004', 'kjv-nature', 110, '4. Dragons & Leviathan', 'Make an evidence card for Dragons & Leviathan. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Job 41; Psalm 74:13–14. Anchor verse (Job 41:1): “Canst thou draw out leviathan with an hook? or his tongue with a cord [which] thou lettest down?” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Mark the speaker and verbs in Job 41 and Psalm 74. Underline the poem''s actions and note what kind of text each passage is.', 'Worked check — Job poses questions about leviathan; the psalm uses dragons and leviathan in poetry about God''s power. Classifying a species requires evidence outside these passages. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-nature/biblical-reality-005/'),
  ('biblical-reality-005', 'kjv-nature', 111, '5. Owls, Ravens & Night Birds', 'Make an evidence card for Owls, Ravens & Night Birds. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Luke 12:24. Anchor verse (Luke 12:24): “Consider the ravens: for they neither sow nor reap; which neither have storehouse nor barn; and God feedeth them: how much more are ye better than the fowls?” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Circle the bird actually named in both readings. Write one line for what the ravens do in Kings and one for what they illustrate in Luke.', 'Worked check — Ravens bring Elijah food; Jesus uses ravens to illustrate provision. These two passages concern ravens specifically. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-nature/biblical-reality-006/'),
  ('biblical-reality-006', 'kjv-nature', 112, '6. Wolves & Lions', 'Make an evidence card for Wolves & Lions. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Genesis 49:9; Genesis 49:27. Anchor verse (Genesis 49:9): “Judah [is] a lion’s whelp: from the prey, my son, thou art gone up: he stooped down, he couched as a lion, and as an old lion; who shall rouse him up?” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Draw two small name cards for Judah and Benjamin. Match each animal image to its tribe and describe what the comparison emphasizes.', 'Worked check — Judah is compared to a lion; Benjamin is compared to a ravening wolf. The images have different jobs in the blessing. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-nature/biblical-reality-007/'),
  ('biblical-reality-007', 'kjv-nature', 113, '7. Goats', 'Make an evidence card for Goats. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Leviticus 16; Leviticus 16:7–10. Anchor verse (Leviticus 16:8): “And Aaron shall cast lots upon the two goats; one lot for the LORD, and the other lot for the scapegoat.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Draw a flowchart for the two goats in Leviticus 16. Trace the lot and destination of each goat using verses 7–10.', 'Worked check — One goat is offered as a sin offering and the other is sent away alive. The text assigns two roles to the same kind of animal. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-nature/biblical-reality-008/'),
  ('biblical-reality-008', 'kjv-nature', 114, '8. Black & Darkness', 'Make an evidence card for Black & Darkness. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Psalm 18:11; 1 Kings 8:12. Anchor verse (Psalm 18:11): “He made darkness his secret place; his pavilion round about him [were] dark waters [and] thick clouds of the skies.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Compare the phrases dark waters and thick darkness. Record who dwells or is described in each passage, then identify the image being used.', 'Worked check — Psalm 18 uses darkness as a covering; 1 Kings 8 records Solomon saying the LORD would dwell in thick darkness. The uses are tied to those settings. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-nature/biblical-reality-009/'),
  ('biblical-reality-009', 'kjv-nature', 115, '9. Crystals, Gemstones & Quartz', 'Make an evidence card for Crystals, Gemstones & Quartz. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Exodus 28:17–20; Revelation 21:19–20. Anchor verse (Exodus 28:17): “And thou shalt set in it settings of stones, [even] four rows of stones: [the first] row [shall be] a sardius, a topaz, and a carbuncle: [this shall be] the first row.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Make two inventory columns for the breastplate and the city foundations. List three stones from each using KJV names.', 'Worked check — The passages list precious stones in different settings. Use the names in the text; where a modern mineral identification is uncertain, leave it open. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-nature/biblical-reality-010/'),
  ('biblical-reality-010', 'kjv-nature', 116, '10. Herbs & Essential Oils', 'Make an evidence card for Herbs & Essential Oils. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Exodus 30:23–25; Mark 14:3; Exodus 30:32–33. Anchor verse (Exodus 30:23): “Take thou also unto thee principal spices, of pure myrrh five hundred [shekels], and of sweet cinnamon half so much, [even] two hundred and fifty [shekels], and of sweet calamus two hundred and fifty [shekels],” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'List one substance and its use from Exodus and another from Mark. Add a boundary box for the oil restriction in Exodus 30:32–33.', 'Worked check — Exodus gives an anointing formula and limits its use. Mark describes spikenard poured in an anointing scene. These passages do not furnish medical directions. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-nature/biblical-reality-011/'),
  ('biblical-reality-011', 'kjv-nature', 117, '11. Trees & Sacred Groves (Planting)', 'Make an evidence card for Trees & Sacred Groves (Planting). Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Genesis 21:33; Deuteronomy 16:21. Anchor verse (Genesis 21:33): “¶ And [Abraham] planted a grove in Beer-sheba, and called there on the name of the LORD, the everlasting God.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Write the KJV noun in Genesis 21:33, then record Abraham''s actions in order. Compare the planted grove with the prohibited planting near an altar in Deuteronomy.', 'Worked check — The KJV says grove. Genesis describes planting and calling on the LORD; Deuteronomy describes a different placement and gives an explicit restriction. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-nature/biblical-reality-012/'),
  ('biblical-reality-012', 'kjv-nature', 118, '12. Thunder & Lightning', 'Make an evidence card for Thunder & Lightning. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Job 37:2–5. Anchor verse (Job 37:2): “Hear attentively the noise of his voice, and the sound [that] goeth out of his mouth.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Underline the sound words in Job 37. Mark where the speaker directly links sound with God''s voice and identify the passage as speech in Job.', 'Worked check — Elihu links thunder with God''s voice and deeds. The activity identifies the text''s image; weather measurements are a separate question. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-nature/biblical-reality-013/'),
  ('biblical-reality-013', 'kjv-nature', 119, '13. The Sea & Deep Waters', 'Make an evidence card for The Sea & Deep Waters. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Genesis 1:10; Genesis 1:9–10. Anchor verse (Genesis 1:10): “And God called the dry [land] Earth; and the gathering together of the waters called he Seas: and God saw that [it was] good.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Draw three boxes for land, gathered waters, and the verdict. Fill them from Genesis 1:9–10 in narrative order.', 'Worked check — God names the gathering of the waters Seas, and the verse says God saw that it was good. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-nature/biblical-reality-014/'),
  ('biblical-reality-014', 'kjv-nature', 120, '14. Salt', 'Make an evidence card for Salt. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Leviticus 2:13; Matthew 5:13. Anchor verse (Leviticus 2:13): “And every oblation of thy meat offering shalt thou season with salt; neither shalt thou suffer the salt of the covenant of thy God to be lacking from thy meat offering: with all thine offerings thou shalt offer salt.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Match salt to the task it performs in Leviticus and the role it plays in the saying in Matthew. Mark literal use and figurative use.', 'Worked check — Leviticus calls for salt with offerings; Matthew calls disciples the salt of the earth. These are distinct uses. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-nature/biblical-reality-015/'),
  ('biblical-reality-015', 'kjv-nature', 121, '15. Fire & Smoke', 'Make an evidence card for Fire & Smoke. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Exodus 13:21; Exodus 19:18. Anchor verse (Exodus 13:21): “And the LORD went before them by day in a pillar of a cloud, to lead them the way; and by night in a pillar of fire, to give them light; to go by day and night:” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Make a day-and-night route sketch. Label the forms of guidance in Exodus 13 and add smoke in its separate Sinai setting.', 'Worked check — Exodus 13 names a cloud by day and fire by night. Exodus 19:18 mentions smoke at Sinai. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-nature/biblical-reality-016/'),
  ('biblical-reality-016', 'kjv-nature', 122, '16. Bones & Skulls', 'Make an evidence card for Bones & Skulls. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Ezekiel 37:1–10; Ezekiel 37:11. Anchor verse (Ezekiel 37:1): “The hand of the LORD was upon me, and carried me out in the spirit of the LORD, and set me down in the midst of the valley which [was] full of bones,” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Sequence the vision as bones, sinews and flesh, then breath. Read the explanation in verse 11 before assigning meaning to the image.', 'Worked check — The vision names dry bones, and verse 11 identifies them with the whole house of Israel. The cited scene centers on bones collectively. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-nature/biblical-reality-017/'),
  ('biblical-reality-017', 'kjv-nature', 123, '17. Blood (Symbol of Life)', 'Make an evidence card for Blood (Symbol of Life). Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Leviticus 17:11; Leviticus 17:10–12. Anchor verse (Leviticus 17:11): “For the life of the flesh [is] in the blood: and I have given it to you upon the altar to make an atonement for your souls: for it [is] the blood [that] maketh an atonement for the soul.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Copy the phrase about the life of the flesh. Place it next to the passage''s altar purpose and the restriction on eating blood.', 'Worked check — Leviticus connects blood with life and with atonement on the altar. The surrounding verses distinguish this from consuming blood. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-nature/biblical-reality-018/'),
  ('biblical-reality-018', 'kjv-nature', 124, '18. The Earth & Soil', 'Make an evidence card for The Earth & Soil. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Genesis 2:7; Genesis 3:19. Anchor verse (Genesis 2:7): “And the LORD God formed man [of] the dust of the ground, and breathed into his nostrils the breath of life; and man became a living soul.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Draw an arrow from dust to formed human to living soul. Add the action associated with breath and compare the return to dust in Genesis 3.', 'Worked check — Genesis 2:7 names dust and breath in the formation account. Genesis 3:19 uses dust in the account of human mortality. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-nature/biblical-reality-019/'),
  ('biblical-reality-019', 'kjv-nature', 125, '19. Plants & Seed-Bearing Herbs', 'Make an evidence card for Plants & Seed-Bearing Herbs. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Genesis 1:29. Anchor verse (Genesis 1:29): “¶ And God said, Behold, I have given you every herb bearing seed, which [is] upon the face of all the earth, and every tree, in the which [is] the fruit of a tree yielding seed; to you it shall be for meat.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Make a two-item pantry list using the kinds of food named in Genesis 1:29. Mark the words that define the kinds being described.', 'Worked check — The verse identifies seed-bearing herbs and fruit-bearing trees for food in its creation setting. It contains no individual plant-safety list. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-nature/biblical-reality-020/'),
  ('biblical-reality-020', 'kjv-nature', 126, '20. Rainbows', 'Make an evidence card for Rainbows. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Genesis 9:13; Genesis 9:14–16. Anchor verse (Genesis 9:13): “I do set my bow in the cloud, and it shall be for a token of a covenant between me and the earth.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Make a covenant card with sign, parties and setting. Find the verse that says who sees the bow and what is remembered.', 'Worked check — The bow is a covenant sign between God and the earth; verses 14–16 describe remembrance in connection with the bow. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-body/')
INSERT INTO academy_way_missions
  (slug, path, position, title, outcome, build, flip, integrate, verify, link)
VALUES
  ('biblical-reality-021', 'kjv-body', 127, '21. Dancing', 'Make an evidence card for Dancing. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — 2 Samuel 6:14; Psalm 149:3. Anchor verse (2 Samuel 6:14): “And David danced before the LORD with all [his] might; and David [was] girded with a linen ephod.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Read the David scene and the psalm. Make a table of who dances, why, and whether the passage reports an event or calls for praise.', 'Worked check — Second Samuel narrates David dancing before the LORD; Psalm 149 calls for praise with dance in its worship setting. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-body/biblical-reality-022/'),
  ('biblical-reality-022', 'kjv-body', 128, '22. Drums & Percussion (Timbrels)', 'Make an evidence card for Drums & Percussion (Timbrels). Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Exodus 15:20; Psalm 150:4. Anchor verse (Exodus 15:20): “¶ And Miriam the prophetess, the sister of Aaron, took a timbrel in her hand; and all the women went out after her with timbrels and with dances.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Find the KJV instrument names and mark the participants. Clap two written patterns to model the contrast between a procession and a general call to praise.', 'Worked check — Exodus names timbrels with Miriam and the women. Psalm 150:4 names timbrel and dance; the rhythm was your illustration. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-body/biblical-reality-023/'),
  ('biblical-reality-023', 'kjv-body', 129, '23. Loud Music & Clashing Cymbals', 'Make an evidence card for Loud Music & Clashing Cymbals. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Psalm 150:5. Anchor verse (Psalm 150:5): “Praise him upon the loud cymbals: praise him upon the high sounding cymbals.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Read Psalm 150 aloud twice, changing volume only where the instrument adjectives suggest it. List the instrument terms actually used in verse 5.', 'Worked check — Verse 5 names loud cymbals and high sounding cymbals. The volume words belong to a call to praise. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-body/biblical-reality-024/'),
  ('biblical-reality-024', 'kjv-body', 130, '24. Stringed Instruments & Harps', 'Make an evidence card for Stringed Instruments & Harps. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — 1 Samuel 16:23. Anchor verse (1 Samuel 16:23): “And it came to pass, when the [evil] spirit from God was upon Saul, that David took an harp, and played with his hand: so Saul was refreshed, and was well, and the evil spirit departed from him.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Place the cause, David''s action, and the reported outcome on a three-panel storyboard. Note exactly who is relieved in the story.', 'Worked check — David plays the harp, and the narrative reports Saul was refreshed and that the evil spirit departed from him. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-body/biblical-reality-025/'),
  ('biblical-reality-025', 'kjv-body', 131, '25. Feasting & Parties', 'Make an evidence card for Feasting & Parties. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — John 2:1–11; John 2:9. Anchor verse (John 2:9): “When the ruler of the feast had tasted the water that was made wine, and knew not whence it was: (but the servants which drew the water knew;) the governor of the feast called the bridegroom,” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Put four wedding details in order. Trace what the governor knows and what the servants know in John 2:9.', 'Worked check — The wedding narrative reports water becoming wine; the servants know where it came from while the governor does not. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-body/biblical-reality-026/'),
  ('biblical-reality-026', 'kjv-body', 132, '26. Wine & Fermented Drink', 'Make an evidence card for Wine & Fermented Drink. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Psalm 104:15; Proverbs 20:1. Anchor verse (Psalm 104:15): “And wine [that] maketh glad the heart of man, [and] oil to make [his] face to shine, and bread [which] strengtheneth man’s heart.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Read the line on gladness beside Proverbs 20:1. Make a two-column chart for benefit and warning with one phrase from each passage.', 'Worked check — Psalm 104 describes wine making the heart glad. Proverbs warns about deception by drink. The two texts address different aspects. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-body/biblical-reality-027/'),
  ('biblical-reality-027', 'kjv-body', 133, '27. Jewelry, Nose Rings & Gold', 'Make an evidence card for Jewelry, Nose Rings & Gold. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Genesis 24:22; Ezekiel 16:11–12; Genesis 24:47. Anchor verse (Genesis 24:22): “And it came to pass, as the camels had done drinking, that the man took a golden earring of half a shekel weight, and two bracelets for her hands of ten [shekels] weight of gold;” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Compare the KJV wording of Genesis 24:22, 47 with Ezekiel''s jewelry image. Underline where Genesis names the placement.', 'Worked check — Genesis 24:22 says golden earring, and verse 47 supplies the face placement in the KJV. Ezekiel 16 uses adornment in an allegory. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-body/biblical-reality-028/'),
  ('biblical-reality-028', 'kjv-body', 134, '28. Makeup & Eye Paint (Kohl)', 'Make an evidence card for Makeup & Eye Paint (Kohl). Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Ezekiel 23:40. Anchor verse (Ezekiel 23:40): “And furthermore, that ye have sent for men to come from far, unto whom a messenger [was] sent; and, lo, they came: for whom thou didst wash thyself, paintedst thy eyes, and deckedst thyself with ornaments,” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Read the painted eyes in Ezekiel 23 as part of its scene. Mark the action and the tone of the surrounding speech.', 'Worked check — The KJV says paintedst thy eyes. The detail appears in a critical allegory. The scene supplies neither a general cosmetics law nor a praise of the people depicted. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-body/biblical-reality-029/'),
  ('biblical-reality-029', 'kjv-body', 135, '29. Perfume & Incense', 'Make an evidence card for Perfume & Incense. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Exodus 30:34–35; Song of Solomon 3:6; Exodus 30:37–38. Anchor verse (Exodus 30:34): “¶ And the LORD said unto Moses, Take unto thee sweet spices, stacte, and onycha, and galbanum; [these] sweet spices with pure frankincense: of each shall there be a like [weight:]” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Make cards for incense formula and poetic image. Match Exodus and Song of Solomon to their cards and locate the restriction on copying the formula.', 'Worked check — Exodus describes a holy incense and restricts duplicating it for personal use. Song 3:6 uses fragrance as a poetic comparison. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-body/biblical-reality-030/'),
  ('biblical-reality-030', 'kjv-body', 136, '30. Long Hair on Men', 'Make an evidence card for Long Hair on Men. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Numbers 6:5; Judges 16:17; 1 Corinthians 11:14. Anchor verse (Numbers 6:5): “All the days of the vow of his separation there shall no razor come upon his head: until the days be fulfilled, in the which he separateth [himself] unto the LORD, he shall be holy, [and] shall let the locks of the hair of his head grow.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Record whose hair appears, who makes a vow, and how a general statement about hair differs from an account of a particular vow.', 'Worked check — Numbers sets a Nazirite rule during a vow; Judges relates Samson''s consecration. First Corinthians 11:14 raises hair in a different setting. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-body/biblical-reality-031/'),
  ('biblical-reality-031', 'kjv-body', 137, '31. Tattoos / Marks of Belonging', 'Make an evidence card for Tattoos / Marks of Belonging. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Isaiah 44:5; Leviticus 19:28. Anchor verse (Isaiah 44:5): “One shall say, I [am] the LORD’s; and another shall call [himself] by the name of Jacob; and another shall subscribe [with] his hand unto the LORD, and surname [himself] by the name of Israel.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Underline what the KJV actually says about the hand in Isaiah. Compare it with the language about marks in Leviticus.', 'Worked check — Isaiah says subscribe with his hand unto the LORD; it does not specify tattooing. Leviticus 19:28 separately addresses marks and practices for the dead. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-body/biblical-reality-032/'),
  ('biblical-reality-032', 'kjv-body', 138, '32. Nakedness Without Shame', 'Make an evidence card for Nakedness Without Shame. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Genesis 2:25; Genesis 3:7. Anchor verse (Genesis 2:25): “And they were both naked, the man and his wife, and were not ashamed.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Compare Genesis 2:25 and Genesis 3:7. Track which detail stays the same and what changes in how the characters respond.', 'Worked check — Both passages describe nakedness. Genesis 2 names absence of shame; Genesis 3 reports that they recognized their state and made coverings. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-body/biblical-reality-033/'),
  ('biblical-reality-033', 'kjv-body', 139, '33. Physical Touch & Embracing', 'Make an evidence card for Physical Touch & Embracing. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Romans 16:16. Anchor verse (Romans 16:16): “Salute one another with an holy kiss. The churches of Christ salute you.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Identify the addressees and the greeting in Romans. Write a respectful greeting today and label it as your application.', 'Worked check — The text specifies a holy kiss among those greeted. A modern equivalent is an application and depends on the people involved. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-body/biblical-reality-034/'),
  ('biblical-reality-034', 'kjv-body', 140, '34. Laughter & Humor', 'Make an evidence card for Laughter & Humor. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Psalm 2:4. Anchor verse (Psalm 2:4): “He that sitteth in the heavens shall laugh: the Lord shall have them in derision.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Read the two uses of laughter in context. Mark which passage names a time to laugh and which depicts divine laughter toward rulers.', 'Worked check — Ecclesiastes sets laughing among seasons of life; Psalm 2 uses divine laughter in a poem about rulers and rebellion. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-body/biblical-reality-035/'),
  ('biblical-reality-035', 'kjv-body', 141, '35. Theater, Parables & Storytelling', 'Make an evidence card for Theater, Parables & Storytelling. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Ezekiel 4; Luke 15. Anchor verse (Ezekiel 4:3): “Moreover take thou unto thee an iron pan, and set it [for] a wall of iron between thee and the city: and set thy face against it, and it shall be besieged, and thou shalt lay siege against it. This [shall be] a sign to the house of Israel.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Sketch Ezekiel''s actions as a sign and map the speakers and listeners in a parable from Luke 15. Explain the format difference.', 'Worked check — Ezekiel 4 narrates enacted signs; Luke 15 records parables told to an audience. The text presents distinct ways of teaching. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-body/biblical-reality-036/'),
  ('biblical-reality-036', 'kjv-body', 142, '36. Poetry & Love Songs', 'Make an evidence card for Poetry & Love Songs. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Song of Solomon; Song of Solomon 2:10–13. Anchor verse (Song of Solomon 2:10): “My beloved spake, and said unto me, Rise up, my love, my fair one, and come away.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Make a two-voice reading of a selected exchange from Song of Solomon. Identify a comparison each speaker makes and avoid assuming an identity from an unlabeled line.', 'Worked check — Song of Solomon 2:10–13 uses an invitation and seasonal imagery. Identify the words on the page before naming the literary or theological interpretation. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-body/biblical-reality-037/'),
  ('biblical-reality-037', 'kjv-body', 143, '37. Sculpture & Visual Art', 'Make an evidence card for Sculpture & Visual Art. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Exodus 31:1–5; Exodus 31:5–6. Anchor verse (Exodus 31:1): “And the LORD spake unto Moses, saying,” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Draw a materials-and-skills chart. Read toward Exodus 31:6 to see which work and co-worker are named.', 'Worked check — The passage names Bezaleel, metalwork, cutting stones, carving timber and wisdom for the work; verse 6 names Aholiab. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-body/biblical-reality-038/'),
  ('biblical-reality-038', 'kjv-body', 144, '38. Masks & Veils', 'Make an evidence card for Masks & Veils. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Exodus 34:33; Exodus 34:29–35. Anchor verse (Exodus 34:33): “And [till] Moses had done speaking with them, he put a vail on his face.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Make a four-step timeline from Exodus 34:29–35. Note when Moses speaks and when he puts on or removes the veil.', 'Worked check — Verses 34–35 describe Moses taking the vail off before the LORD and putting it on again before returning to speak with him. The KJV spells the covering vail. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-body/biblical-reality-039/'),
  ('biblical-reality-039', 'kjv-body', 145, '39. Banners & Flags', 'Make an evidence card for Banners & Flags. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Psalm 20:5; Song of Solomon 2:4. Anchor verse (Psalm 20:5): “We will rejoice in thy salvation, and in the name of our God we will set up [our] banners: the LORD fulfil all thy petitions.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Compare how a banner functions in the psalm and in the love poem. Write one phrase from each that justifies your reading.', 'Worked check — Psalm 20 ties banners to salvation and God''s name. Song of Solomon describes a banner of love. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-body/biblical-reality-040/'),
  ('biblical-reality-040', 'kjv-body', 146, '40. Meditation & Deep Quiet', 'Make an evidence card for Meditation & Deep Quiet. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Genesis 24:63; Psalm 1:2. Anchor verse (Genesis 24:63): “And Isaac went out to meditate in the field at the eventide: and he lifted up his eyes, and saw, and, behold, the camels [were] coming.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Record the scene, time of day, and action in Genesis. Compare the object and rhythm of meditation in Psalm 1.', 'Worked check — Isaac goes into the field at eventide in the KJV. Psalm 1 speaks of meditating in the LORD''s law day and night. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-dreams/')
INSERT INTO academy_way_missions
  (slug, path, position, title, outcome, build, flip, integrate, verify, link)
VALUES
  ('biblical-reality-041', 'kjv-dreams', 147, '41. Lucid & Prophetic Dreams', 'Make an evidence card for Lucid & Prophetic Dreams. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Genesis 28:12; Daniel 2; Genesis 37:5; Daniel 2:19. Anchor verse (Genesis 28:12): “And he dreamed, and behold a ladder set up on the earth, and the top of it reached to heaven: and behold the angels of God ascending and descending on it.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Make one card each for Jacob, Joseph, and Daniel. Note who dreamed, who interpreted, and who received instruction.', 'Worked check — Jacob and Joseph are shown dreaming in Genesis; Daniel 2 distinguishes the king''s dream from the secret revealed to Daniel in a night vision. The text does not classify the episodes as lucid dreaming. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-dreams/biblical-reality-042/'),
  ('biblical-reality-042', 'kjv-dreams', 148, '42. Interpreting Dreams', 'Make an evidence card for Interpreting Dreams. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Genesis 40:8; Daniel 2:27–28. Anchor verse (Genesis 40:8): “And they said unto him, We have dreamed a dream, and [there is] no interpreter of it. And Joseph said unto them, [Do] not interpretations [belong] to God? tell me [them], I pray you.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Read Genesis 40:8 and Daniel 2:27–28. Circle who each speaker says supplies the interpretation or revelation.', 'Worked check — Joseph says interpretations belong to God; Daniel says God in heaven reveals secrets. The two speakers distinguish themselves from the source they name. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-dreams/biblical-reality-043/'),
  ('biblical-reality-043', 'kjv-dreams', 149, '43. Visions & Trances', 'Make an evidence card for Visions & Trances. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Acts 10:10; Acts 22:17; Acts 10:9–11. Anchor verse (Acts 10:10): “And he became very hungry, and would have eaten: but while they made ready, he fell into a trance,” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Draw separate settings for Acts 10 and Acts 22. Record where the trance happens and what the next scene does with it.', 'Worked check — Acts 10 sets Peter''s trance in a rooftop prayer episode; Acts 22 recounts Paul''s trance while praying in the temple. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-dreams/biblical-reality-044/'),
  ('biblical-reality-044', 'kjv-dreams', 150, '44. Out-of-Body / Spirit Travel', 'Make an evidence card for Out-of-Body / Spirit Travel. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — 2 Corinthians 12:2. Anchor verse (2 Corinthians 12:2): “I knew a man in Christ above fourteen years ago, (whether in the body, I cannot tell; or whether out of the body, I cannot tell: God knoweth;) such an one caught up to the third heaven.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Copy the alternatives Paul repeats and circle the words that state his uncertainty. Make separate boxes for what he reports and what he leaves open.', 'Worked check — Paul says he cannot tell whether it was in the body or out of the body. The account leaves that question unresolved. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-dreams/biblical-reality-045/'),
  ('biblical-reality-045', 'kjv-dreams', 151, '45. Angels & Spirit Messengers', 'Make an evidence card for Angels & Spirit Messengers. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Hebrews 13:2; Genesis 18:2; Genesis 19:1. Anchor verse (Hebrews 13:2): “Be not forgetful to entertain strangers: for thereby some have entertained angels unawares.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Underline the advice in Hebrews 13. Use Genesis 18–19 to note how the visitors are described at different points in the narratives.', 'Worked check — Hebrews encourages hospitality to strangers, some having entertained angels unawares. Genesis uses descriptions including men and angels in the two chapters. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-dreams/biblical-reality-046/'),
  ('biblical-reality-046', 'kjv-dreams', 152, '46. Casting Lots (Random Decision Making)', 'Make an evidence card for Casting Lots (Random Decision Making). Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Acts 1:26; Proverbs 16:33; Acts 1:23–26. Anchor verse (Acts 1:26): “And they gave forth their lots; and the lot fell upon Matthias; and he was numbered with the eleven apostles.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Diagram the steps before the lot in Acts 1: candidates, prayer, and outcome. Name the selected person from the verse.', 'Worked check — The group presents two candidates, prays, and casts lots. The lot falls upon Matthias. The earlier steps belong in the record. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-dreams/biblical-reality-047/'),
  ('biblical-reality-047', 'kjv-dreams', 153, '47. Urim and Thummim', 'Make an evidence card for Urim and Thummim. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Exodus 28:30; Numbers 27:21. Anchor verse (Exodus 28:30): “¶ And thou shalt put in the breastplate of judgment the Urim and the Thummim; and they shall be upon Aaron’s heart, when he goeth in before the LORD: and Aaron shall bear the judgment of the children of Israel upon his heart before the LORD continually.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Mark where the objects are placed and whose role the text names. Read Numbers 27:21 to compare their stated function.', 'Worked check — Exodus places Urim and Thummim in the breastplate of judgment. Numbers describes priestly inquiry with Urim. Neither describes how to manufacture them. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-dreams/biblical-reality-048/'),
  ('biblical-reality-048', 'kjv-dreams', 154, '48. Fleece Signs (Testing for Confirmation)', 'Make an evidence card for Fleece Signs (Testing for Confirmation). Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Judges 6:36–40. Anchor verse (Judges 6:36): “¶ And Gideon said unto God, If thou wilt save Israel by mine hand, as thou hast said,” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Draw two boxes showing wet and dry fleece and ground. Fill them from the two successive requests and verify that the outcomes are reversed.', 'Worked check — First the fleece is wet and the ground dry; then the fleece is dry and the ground wet in Gideon''s narrated request. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-dreams/biblical-reality-049/'),
  ('biblical-reality-049', 'kjv-dreams', 155, '49. Intuition & Inner Knowing', 'Make an evidence card for Intuition & Inner Knowing. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Jeremiah 31:33. Anchor verse (Jeremiah 31:33): “But this [shall be] the covenant that I will make with the house of Israel; After those days, saith the LORD, I will put my law in their inward parts, and write it in their hearts; and will be their God, and they shall be my people.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Copy the actor, action and recipients of the covenant statement. Keep the inner placement and what is written in separate fields.', 'Worked check — Jeremiah says God will put his law in their inward parts and write it in their hearts. The object named is the law. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-dreams/biblical-reality-050/'),
  ('biblical-reality-050', 'kjv-dreams', 156, '50. Fasting for Clarity', 'Make an evidence card for Fasting for Clarity. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Matthew 6:16–18. Anchor verse (Matthew 6:16): “¶ Moreover when ye fast, be not, as the hypocrites, of a sad countenance: for they disfigure their faces, that they may appear unto men to fast. Verily I say unto you, They have their reward.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'On paper, compare how the people described display fasting with how Jesus advises his hearers to act. Complete the exercise through reading and annotation.', 'Worked check — Matthew contrasts making fasting conspicuous with directing the action toward the Father in secret. The passage gives no timed fasting regimen. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-dreams/biblical-reality-051/'),
  ('biblical-reality-051', 'kjv-dreams', 157, '51. Night Watches & Staying Awake', 'Make an evidence card for Night Watches & Staying Awake. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Psalm 63:6. Anchor verse (Psalm 63:6): “When I remember thee upon my bed, [and] meditate on thee in the [night] watches.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Place remembered, meditate and night watches on a reading timeline. Identify what the verse says about meditation and what it specifies about sleep.', 'Worked check — The verse describes remembering and meditating in the night watches. It sets no duration of sleep or wakefulness. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-dreams/biblical-reality-052/'),
  ('biblical-reality-052', 'kjv-dreams', 158, '52. Speaking in Unknown Tongues / Ecstatic Speech', 'Make an evidence card for Speaking in Unknown Tongues / Ecstatic Speech. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — 1 Corinthians 14:2; 1 Corinthians 14:27–28. Anchor verse (1 Corinthians 14:2): “For he that speaketh in an [unknown] tongue speaketh not unto men, but unto God: for no man understandeth [him]; howbeit in the spirit he speaketh mysteries.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Make a table with speaker, audience and comprehension. Use 1 Corinthians 14:2 and 27–28 to identify what changes when interpretation is available.', 'Worked check — Verse 2 speaks of mysteries in the spirit. Verses 27–28 address public order and say to keep silence in church if there is no interpreter. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-dreams/biblical-reality-053/'),
  ('biblical-reality-053', 'kjv-dreams', 159, '53. Prophetic Riddles & Metaphors', 'Make an evidence card for Prophetic Riddles & Metaphors. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Judges 14:12; Ezekiel 17:2; Judges 14:14; Ezekiel 17:11–14. Anchor verse (Judges 14:12): “¶ And Samson said unto them, I will now put forth a riddle unto you: if ye can certainly declare it me within the seven days of the feast, and find [it] out, then I will give you thirty sheets and thirty change of garments:” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Take a riddle and a parable in their own settings. List speaker, audience and how the answer becomes known in each.', 'Worked check — Samson poses a riddle to companions; Ezekiel is directed to speak a riddle and parable to Israel. The surrounding chapters give their individual settings. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-dreams/biblical-reality-054/'),
  ('biblical-reality-054', 'kjv-dreams', 160, '54. Seeing Spirits / Open Eyes', 'Make an evidence card for Seeing Spirits / Open Eyes. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — 2 Kings 6:17; 2 Kings 6:15. Anchor verse (2 Kings 6:17): “And Elisha prayed, and said, LORD, I pray thee, open his eyes, that he may see. And the LORD opened the eyes of the young man; and he saw: and, behold, the mountain [was] full of horses and chariots of fire round about Elisha.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Draw two snapshots, what the servant first sees and what he sees after Elisha prays. Anchor both snapshots in separate verse numbers.', 'Worked check — Second Kings 6:15 reports the surrounding force. Verse 17 reports the mountain full of horses and chariots of fire after the servant''s eyes open. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-dreams/biblical-reality-055/'),
  ('biblical-reality-055', 'kjv-dreams', 161, '55. Discernment of Spirits', 'Make an evidence card for Discernment of Spirits. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — 1 Corinthians 12:10; 1 Corinthians 12:7–11. Anchor verse (1 Corinthians 12:10): “To another the working of miracles; to another prophecy; to another discerning of spirits; to another [divers] kinds of tongues; to another the interpretation of tongues:” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Find the named gift and two gifts immediately beside it. Compare diversity of gifts in the previous verses.', 'Worked check — The KJV says discerning of spirits, beside prophecy and tongues in the list. The passage assigns different gifts within the group. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-dreams/biblical-reality-056/'),
  ('biblical-reality-056', 'kjv-dreams', 162, '56. Sacred Silence', 'Make an evidence card for Sacred Silence. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Revelation 8:1; Revelation 8:1–3. Anchor verse (Revelation 8:1): “And when he had opened the seventh seal, there was silence in heaven about the space of half an hour.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Build a sequence for the seventh seal and the next two events. Mark the duration as the text states it.', 'Worked check — Revelation says there was silence in heaven about the space of half an hour after the seventh seal opened. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-dreams/biblical-reality-057/'),
  ('biblical-reality-057', 'kjv-dreams', 163, '57. Groaning Without Words', 'Make an evidence card for Groaning Without Words. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Romans 8:26; Romans 8:22–27. Anchor verse (Romans 8:26): “Likewise the Spirit also helpeth our infirmities: for we know not what we should pray for as we ought: but the Spirit itself maketh intercession for us with groanings which cannot be uttered.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Read Romans 8:22–27 and make one row for each use of groaning. Identify who intercedes in verse 26.', 'Worked check — The chapter distinguishes creation''s groaning, our groaning, and the Spirit''s intercession with groanings which cannot be uttered. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-dreams/biblical-reality-058/'),
  ('biblical-reality-058', 'kjv-dreams', 164, '58. Miracles & Wonders', 'Make an evidence card for Miracles & Wonders. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Acts 2:22; Acts 2:14. Anchor verse (Acts 2:22): “Ye men of Israel, hear these words; Jesus of Nazareth, a man approved of God among you by miracles and wonders and signs, which God did by him in the midst of you, as ye yourselves also know:” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Find the three terms Peter uses in Acts 2:22. Identify Peter''s audience and the person to whom he ascribes the actions.', 'Worked check — The speech names miracles, wonders and signs and says God did them by Jesus among the hearers. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-dreams/biblical-reality-059/'),
  ('biblical-reality-059', 'kjv-dreams', 165, '59. Shadows Healing People', 'Make an evidence card for Shadows Healing People. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Acts 5:15; Acts 5:15–16. Anchor verse (Acts 5:15): “Insomuch that they brought forth the sick into the streets, and laid [them] on beds and couches, that at the least the shadow of Peter passing by might overshadow some of them.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Make two columns headed Hope and Reported Outcome. Place Acts 5:15 and 5:16 in the appropriate columns.', 'Worked check — Verse 15 explains why people placed the sick in the streets; verse 16 reports healings in the surrounding scene. The distinction is about what each verse actually says. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-dreams/biblical-reality-060/'),
  ('biblical-reality-060', 'kjv-dreams', 166, '60. Handkerchiefs & Aprons Carrying Healing', 'Make an evidence card for Handkerchiefs & Aprons Carrying Healing. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Acts 19:12; Acts 19:11–12. Anchor verse (Acts 19:12): “So that from his body were brought unto the sick handkerchiefs or aprons, and the diseases departed from them, and the evil spirits went out of them.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Underline the items named in Acts 19. Read the preceding verse and identify the actor to whom Luke attributes the miracles.', 'Worked check — Verse 11 says God wrought special miracles by Paul; verse 12 names handkerchiefs or aprons. It records a narrative, without instructions for making a healing object. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-remembrance/')
INSERT INTO academy_way_missions
  (slug, path, position, title, outcome, build, flip, integrate, verify, link)
VALUES
  ('biblical-reality-061', 'kjv-remembrance', 167, '61. Honoring Ancestors & Genealogy', 'Make an evidence card for Honoring Ancestors & Genealogy. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Genesis 5; Matthew 1. Anchor verse (Genesis 5:1): “This [is] the book of the generations of Adam. In the day that God created man, in the likeness of God made he him;” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Build a three-name sequence from each genealogy. Mark how the KJV introduction in each book identifies the purpose of the record.', 'Worked check — Genesis 5 identifies the generations of Adam; Matthew 1 begins with Jesus Christ, David and Abraham. Both preserve lineages with different frames. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-remembrance/biblical-reality-062/'),
  ('biblical-reality-062', 'kjv-remembrance', 168, '62. Visiting & Tending Graves', 'Make an evidence card for Visiting & Tending Graves. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — John 11:38; Mark 16:1. Anchor verse (John 11:38): “Jesus therefore again groaning in himself cometh to the grave. It was a cave, and a stone lay upon it.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Sketch the approach to Lazarus''s grave and the women''s trip with spices. Keep the purposes and the outcome separate.', 'Worked check — John describes Jesus coming to Lazarus''s grave. Mark 16 says the women came with spices to anoint Jesus and describes what they found. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-remembrance/biblical-reality-063/'),
  ('biblical-reality-063', 'kjv-remembrance', 169, '63. Memorial Stones & Altars of Remembrance', 'Make an evidence card for Memorial Stones & Altars of Remembrance. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Joshua 4:6–7; Joshua 4:4–7. Anchor verse (Joshua 4:6): “That this may be a sign among you, [that] when your children ask [their fathers] in time to come, saying, What [mean] ye by these stones?” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Make a sign card for a child asking about the stones. Name who asks, who answers, and what event the reply recalls.', 'Worked check — Joshua calls the stones a memorial and records the question and explanation about the waters of Jordan. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-remembrance/biblical-reality-064/'),
  ('biblical-reality-064', 'kjv-remembrance', 170, '64. Speaking the Names of the Dead', 'Make an evidence card for Speaking the Names of the Dead. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Deuteronomy 25:6; Deuteronomy 25:5–6. Anchor verse (Deuteronomy 25:6): “And it shall be, [that] the firstborn which she beareth shall succeed in the name of his brother [which is] dead, that his name be not put out of Israel.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Copy the phrase about a name being blotted out and identify the family-law situation in the preceding verse.', 'Worked check — Deuteronomy 25:6 addresses preserving a dead brother''s name through the family provision described in verse 5. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-remembrance/biblical-reality-065/'),
  ('biblical-reality-065', 'kjv-remembrance', 171, '65. Mourning Rituals & Lamentation', 'Make an evidence card for Mourning Rituals & Lamentation. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Psalm 56:8; Ecclesiastes 3:4; Genesis 37:34. Anchor verse (Psalm 56:8): “Thou tellest my wanderings: put thou my tears into thy bottle: [are they] not in thy book?” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Mark where the readings use literal time language and imagery. Compare a further text where sackcloth accompanies mourning.', 'Worked check — Psalm 56 pictures tears in God''s bottle; Ecclesiastes names a time to mourn; Genesis 37:34 explicitly describes sackcloth and mourning. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-remembrance/biblical-reality-066/'),
  ('biblical-reality-066', 'kjv-remembrance', 172, '66. Funerary Spices & Anointing Bodies', 'Make an evidence card for Funerary Spices & Anointing Bodies. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — John 19:39–40. Anchor verse (John 19:39): “And there came also Nicodemus, which at the first came to Jesus by night, and brought a mixture of myrrh and aloes, about an hundred pound [weight].” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Make an inventory of materials, people, and actions in John 19. Circle the description that connects the actions with burial custom.', 'Worked check — John records myrrh and aloes brought by Nicodemus and linen with spices, described as the manner of burial. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-remembrance/biblical-reality-067/'),
  ('biblical-reality-067', 'kjv-remembrance', 173, '67. Family Burial Caves', 'Make an evidence card for Family Burial Caves. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Genesis 23:19; Genesis 23:16–20. Anchor verse (Genesis 23:19): “And after this, Abraham buried Sarah his wife in the cave of the field of Machpelah before Mamre: the same [is] Hebron in the land of Canaan.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Draw a simple property record: buyer, seller, location, and first burial. Check the transaction in the immediate context.', 'Worked check — Genesis 23 describes Abraham buying Ephron''s field and cave at Machpelah and burying Sarah there. Later family burials need their own references. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-remembrance/biblical-reality-068/'),
  ('biblical-reality-068', 'kjv-remembrance', 174, '68. Eulogies & Songs for the Departed', 'Make an evidence card for Eulogies & Songs for the Departed. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — 2 Samuel 1:17–27. Anchor verse (2 Samuel 1:19): “The beauty of Israel is slain upon thy high places: how are the mighty fallen!” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Choose one repeated line from the lament and read it aloud at two places in the poem. Identify whom David is lamenting.', 'Worked check — David''s lament names Saul and Jonathan and repeats the fallen mighty image. The KJV calls it a lamentation. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-remembrance/biblical-reality-069/'),
  ('biblical-reality-069', 'kjv-remembrance', 175, '69. Passing Down Blessings on a Deathbed', 'Make an evidence card for Passing Down Blessings on a Deathbed. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Genesis 49; Genesis 49:28. Anchor verse (Genesis 49:28): “¶ All these [are] the twelve tribes of Israel: and this [is it] that their father spake unto them, and blessed them; every one according to his blessing he blessed them.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Choose three sons in Genesis 49 and copy a different phrase directed to each. Flag where a saying is a rebuke or prediction.', 'Worked check — The chapter calls the speech a blessing while individual sayings differ in form and tone. The distinctions are visible in the lines chosen. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-remembrance/biblical-reality-070/'),
  ('biblical-reality-070', 'kjv-remembrance', 176, '70. The Cloud of Witnesses', 'Make an evidence card for The Cloud of Witnesses. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Hebrews 12:1. Anchor verse (Hebrews 12:1): “Wherefore seeing we also are compassed about with so great a cloud of witnesses, let us lay aside every weight, and the sin which doth so easily beset [us], and let us run with patience the race that is set before us,” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Draw a link between Hebrews 11''s examples and the race in Hebrews 12:1. Identify what readers are instructed to do.', 'Worked check — The verse names a cloud of witnesses then urges laying aside weight and running with patience. It does not specify what the witnesses perceive. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-remembrance/biblical-reality-071/'),
  ('biblical-reality-071', 'kjv-remembrance', 177, '71. Moses & Elijah Appearing Alive', 'Make an evidence card for Moses & Elijah Appearing Alive. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Matthew 17:3; Matthew 17:1–9. Anchor verse (Matthew 17:3): “And, behold, there appeared unto them Moses and Elias talking with him.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Create a timeline from the beginning of the scene through Matthew 17:9. Distinguish what the disciples are said to see from later interpretations.', 'Worked check — Moses and Elias appear talking with Jesus. Verse 9 refers to the experience as a vision in the KJV. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-remembrance/biblical-reality-072/'),
  ('biblical-reality-072', 'kjv-remembrance', 178, '72. Sleep as a Metaphor for Death', 'Make an evidence card for Sleep as a Metaphor for Death. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — 1 Thessalonians 4:13; 1 Thessalonians 4:13–14. Anchor verse (1 Thessalonians 4:13): “But I would not have you to be ignorant, brethren, concerning them which are asleep, that ye sorrow not, even as others which have no hope.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Copy the expression used for the dead in verses 13 and 14. Record the specific grief and hope contrast in the addressed community.', 'Worked check — Paul uses asleep/sleep language and addresses sorrow in light of resurrection hope. The term is part of his pastoral argument. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-remembrance/biblical-reality-073/'),
  ('biblical-reality-073', 'kjv-remembrance', 179, '73. Dust Returning to Earth', 'Make an evidence card for Dust Returning to Earth. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Ecclesiastes 12:7; Genesis 3:19. Anchor verse (Ecclesiastes 12:7): “Then shall the dust return to the earth as it was: and the spirit shall return unto God who gave it.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Write two separate arrows for dust and spirit from Ecclesiastes 12:7. Compare the dust wording with Genesis 3:19.', 'Worked check — Ecclesiastes says the dust returns to earth and the spirit returns to God who gave it. Genesis 3:19 parallels the dust language. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-remembrance/biblical-reality-074/'),
  ('biblical-reality-074', 'kjv-remembrance', 180, '74. Inheritances & Heirlooms', 'Make an evidence card for Inheritances & Heirlooms. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Proverbs 13:22. Anchor verse (Proverbs 13:22): “A good [man] leaveth an inheritance to his children’s children: and the wealth of the sinner [is] laid up for the just.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Draw three generations and mark who gives and who receives in the proverb. Put the second half of the proverb on a separate line.', 'Worked check — Proverbs names an inheritance for children''s children and contrasts the good person with the sinner. It does not specify an heirloom or amount. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-remembrance/biblical-reality-075/'),
  ('biblical-reality-075', 'kjv-remembrance', 181, '75. Oral Storytelling Across Generations', 'Make an evidence card for Oral Storytelling Across Generations. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Psalm 78:3–4; Psalm 78:12–16. Anchor verse (Psalm 78:3): “Which we have heard and known, and our fathers have told us.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Take one event from Psalm 78:12–16 and retell it in two sentences. Exchange it with a partner and mark any detail your retelling added.', 'Worked check — Psalm 78 tells one generation to pass on the LORD''s works to the next. A retelling should keep the selected event identifiable in the text. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-mind/')
INSERT INTO academy_way_missions
  (slug, path, position, title, outcome, build, flip, integrate, verify, link)
VALUES
  ('biblical-reality-076', 'kjv-mind', 182, '76. Questioning Authority & Asking "Why?"', 'Make an evidence card for Questioning Authority & Asking "Why?". Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Job 21; Habakkuk 1:2; Job 21:7; Psalm 13:1. Anchor verse (Habakkuk 1:2): “O LORD, how long shall I cry, and thou wilt not hear! [even] cry out unto thee [of] violence, and thou wilt not save!” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Write the exact questions from Job and Habakkuk and identify to whom each is spoken. Read a Psalm 13 question as a third example.', 'Worked check — Job 21:7 questions why the wicked live; Habakkuk asks how long his cry will go unanswered; Psalm 13 also uses How long. The speakers and situations differ. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-mind/biblical-reality-077/'),
  ('biblical-reality-077', 'kjv-mind', 183, '77. Doubt & Asking for Proof', 'Make an evidence card for Doubt & Asking for Proof. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — John 20:27; John 20:25–29. Anchor verse (John 20:27): “Then saith he to Thomas, Reach hither thy finger, and behold my hands; and reach hither thy hand, and thrust [it] into my side: and be not faithless, but believing.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Put Thomas''s demand beside Jesus'' reply. Note which actions are requested, offered and explicitly recorded next.', 'Worked check — Thomas asks for touch as evidence. Jesus invites him to touch; the passage records Thomas''s answer without explicitly narrating that he touched. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-mind/biblical-reality-078/'),
  ('biblical-reality-078', 'kjv-mind', 184, '78. Critical Thinking & Testing Everything', 'Make an evidence card for Critical Thinking & Testing Everything. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — 1 Thessalonians 5:21; 1 Thessalonians 5:19–22. Anchor verse (1 Thessalonians 5:21): “Prove all things; hold fast that which is good.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Read the injunction with the preceding verse and the following verse. Test a sample interpretation against all three before writing a rule in your own words.', 'Worked check — First Thessalonians places proving all things between despising not prophesyings and abstaining from appearance of evil. The verse says to hold fast that which is good. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-mind/biblical-reality-079/'),
  ('biblical-reality-079', 'kjv-mind', 185, '79. Secular Philosophy & Poetry', 'Make an evidence card for Secular Philosophy & Poetry. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Acts 17:28; Acts 17:22–28. Anchor verse (Acts 17:28): “For in him we live, and move, and have our being; as certain also of your own poets have said, For we are also his offspring.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Underline what Paul attributes to certain poets. Mark any names that appear in the KJV verse itself, then write what additional evidence would identify the authors.', 'Worked check — Acts attributes language to certain of your own poets and names none there. Author identifications are historical cross-references requiring their own evidence. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-mind/biblical-reality-080/'),
  ('biblical-reality-080', 'kjv-mind', 186, '80. Foreign Wisdom & Science', 'Make an evidence card for Foreign Wisdom & Science. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Daniel 1:17; Daniel 1:4. Anchor verse (Daniel 1:17): “¶ As for these four children, God gave them knowledge and skill in all learning and wisdom: and Daniel had understanding in all visions and dreams.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Compare Moses'' education with Daniel and his companions'' learning. Circle the KJV words used to describe the learning in each case.', 'Worked check — Acts names the wisdom of the Egyptians; Daniel names knowledge, skill in learning, and wisdom. The passages need not refer to the same curriculum. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-mind/biblical-reality-081/'),
  ('biblical-reality-081', 'kjv-mind', 187, '81. Wealth & Prosperity', 'Make an evidence card for Wealth & Prosperity. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Genesis 13:2; Job 1:3; 1 Kings 3:12–13. Anchor verse (Genesis 13:2): “And Abram [was] very rich in cattle, in silver, and in gold.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Make a ledger for Abram, Job, and Solomon and record how each passage identifies wealth. Flag any prediction of automatic prosperity that the passages do not state.', 'Worked check — Genesis names Abram''s cattle, silver and gold; Job lists possessions; 1 Kings narrates riches in Solomon''s particular account. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-mind/biblical-reality-082/'),
  ('biblical-reality-082', 'kjv-mind', 188, '82. Rest, Leisure & Doing Nothing (Sabbath)', 'Make an evidence card for Rest, Leisure & Doing Nothing (Sabbath). Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Exodus 20:8–10; Deuteronomy 5:12–15. Anchor verse (Exodus 20:8): “Remember the sabbath day, to keep it holy.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Compare the Sabbath instructions in Exodus and Deuteronomy. List who rests and the reason each version presents.', 'Worked check — Exodus grounds the command in creation and rest. Deuteronomy recalls servitude and deliverance and explicitly mentions rest for servants. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-mind/biblical-reality-083/'),
  ('biblical-reality-083', 'kjv-mind', 189, '83. Anger at Injustice', 'Make an evidence card for Anger at Injustice. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Matthew 21:12; Matthew 21:12–13. Anchor verse (Matthew 21:12): “¶ And Jesus went into the temple of God, and cast out all them that sold and bought in the temple, and overthrew the tables of the moneychangers, and the seats of them that sold doves,” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Sequence Jesus'' actions in Matthew 21 and add his spoken reasons from verse 13. Separate the action verbs from any emotion you infer.', 'Worked check — The passage reports expulsion and overturned tables, then quotes the house of prayer and den of thieves contrast. Matthew 21:12 doesn''t name an emotion. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-mind/biblical-reality-084/'),
  ('biblical-reality-084', 'kjv-mind', 190, '84. Refusing Blind Obedience', 'Make an evidence card for Refusing Blind Obedience. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Exodus 1:17; Exodus 1:15–21. Anchor verse (Exodus 1:17): “But the midwives feared God, and did not as the king of Egypt commanded them, but saved the men children alive.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Write Pharaoh''s order on one card and the midwives'' action on another. Quote the motive the narrator gives in verse 17.', 'Worked check — The midwives feared God and did not obey the king''s command to kill the boys. Exodus names Shiphrah and Puah in verse 15. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-mind/biblical-reality-085/'),
  ('biblical-reality-085', 'kjv-mind', 191, '85. Women Leading & Prophesying', 'Make an evidence card for Women Leading & Prophesying. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — 2 Kings 22:14; Exodus 15:20; Judges 4:4–5. Anchor verse (2 Kings 22:14): “So Hilkiah the priest, and Ahikam, and Achbor, and Shaphan, and Asahiah, went unto Huldah the prophetess, the wife of Shallum the son of Tikvah, the son of Harhas, keeper of the wardrobe; (now she dwelt in Jerusalem in the college;) and they communed with her.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Create a role table for Deborah, Miriam and Huldah. Give each her own source line and identify the verb or title that establishes the role.', 'Worked check — Judges calls Deborah a prophetess and says she judged Israel. Exodus names Miriam as a prophetess; 2 Kings names Huldah as a prophetess. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-mind/biblical-reality-086/'),
  ('biblical-reality-086', 'kjv-mind', 192, '86. Foreigners & Outsiders Grafted In', 'Make an evidence card for Foreigners & Outsiders Grafted In. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Matthew 1:5; Ruth 1:4; Joshua 2:1. Anchor verse (Matthew 1:5): “And Salmon begat Booz of Rachab; and Booz begat Obed of Ruth; and Obed begat Jesse;” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Trace Matthew 1:5–6 and name the women its KJV spelling names. Check where Ruth and Rahab are identified in earlier books.', 'Worked check — Matthew names Rachab and Ruth in the genealogy. Ruth 1 identifies Ruth as a Moabitess; Joshua introduces Rahab in Jericho. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-mind/biblical-reality-087/'),
  ('biblical-reality-087', 'kjv-mind', 193, '87. Samaritans (Cultural Outcasts)', 'Make an evidence card for Samaritans (Cultural Outcasts). Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Luke 10:33; Luke 10:30–37. Anchor verse (Luke 10:33): “But a certain Samaritan, as he journeyed, came where he was: and when he saw him, he had compassion [on him],” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Make a map of who sees, who responds, and what help is given in the parable. Read Jesus'' closing question and answer it from the passage.', 'Worked check — The Samaritan has compassion and acts; Jesus ends by asking which was neighbour, and the hearer identifies the one who showed mercy. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-mind/biblical-reality-088/'),
  ('biblical-reality-088', 'kjv-mind', 194, '88. Eating Any Food Without Religious Taboo', 'Make an evidence card for Eating Any Food Without Religious Taboo. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Mark 7:19; Acts 10:15; Mark 7:18–23; Acts 10:28. Anchor verse (Mark 7:19): “Because it entereth not into his heart, but into the belly, and goeth out into the draught, purging all meats?” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Read Mark 7''s food and defilement language, then check Peter''s own explanation of the vision in Acts 10:28. Put the two claims side by side.', 'Worked check — Mark discusses what enters the body and what comes out of the heart. Peter applies the vision to calling no person common or unclean. Record the application each passage gives. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-mind/biblical-reality-089/'),
  ('biblical-reality-089', 'kjv-mind', 195, '89. Not Observing Special Religious Days', 'Make an evidence card for Not Observing Special Religious Days. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Romans 14:5; Romans 14:4–6. Anchor verse (Romans 14:5): “One man esteemeth one day above another: another esteemeth every day [alike]. Let every man be fully persuaded in his own mind.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Make a paired example of people who esteem days differently. Check how Paul tells them to act toward each other in the surrounding verses.', 'Worked check — Romans 14 allows differing esteem of days and says each should be fully persuaded in his own mind. The debate sits inside an argument against judging one another. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-mind/biblical-reality-090/'),
  ('biblical-reality-090', 'kjv-mind', 196, '90. Living Outside Institutional Buildings', 'Make an evidence card for Living Outside Institutional Buildings. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Acts 7:48; Acts 7:44–50. Anchor verse (Acts 7:48): “Howbeit the most High dwelleth not in temples made with hands; as saith the prophet,” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Read the sequence from tabernacle to temple in Acts 7:44–50. Note who built the house and what Stephen then says about dwelling.', 'Worked check — Stephen mentions Solomon building a house, then says the Most High does not dwell in temples made with hands. The sequence is about God''s dwelling. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-mind/biblical-reality-091/'),
  ('biblical-reality-091', 'kjv-mind', 197, '91. Self-Love & Caring for Your Own Body', 'Make an evidence card for Self-Love & Caring for Your Own Body. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Mark 12:31; Ephesians 5:29. Anchor verse (Mark 12:31): “And the second [is] like, [namely] this, Thou shalt love thy neighbour as thyself. There is none other commandment greater than these.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Copy the neighbour comparison from Mark. Write one practical example of nourishing or cherishing from Ephesians and label it as your example.', 'Worked check — Mark gives love of neighbour as thyself; Ephesians uses nourishing and cherishing flesh as a comparison. The activity retains both contexts. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-mind/biblical-reality-092/'),
  ('biblical-reality-092', 'kjv-mind', 198, '92. Friendship & Deep Loyalty', 'Make an evidence card for Friendship & Deep Loyalty. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — 1 Samuel 18:1–3; 1 Samuel 18:1–4. Anchor verse (1 Samuel 18:1): “And it came to pass, when he had made an end of speaking unto Saul, that the soul of Jonathan was knit with the soul of David, and Jonathan loved him as his own soul.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Make a list of actions that show Jonathan''s loyalty. Compare a modern retelling against the actions and mark where it adds motives.', 'Worked check — First Samuel describes the bond, love, covenant and gifts. A retelling can distinguish these narrated actions from motives not stated. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-mind/biblical-reality-093/'),
  ('biblical-reality-093', 'kjv-mind', 199, '93. Animals Having Breath & Spirit', 'Make an evidence card for Animals Having Breath & Spirit. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Ecclesiastes 3:19; Ecclesiastes 3:19–22. Anchor verse (Ecclesiastes 3:19): “For that which befalleth the sons of men befalleth beasts; even one thing befalleth them: as the one dieth, so dieth the other; yea, they have all one breath; so that a man hath no preeminence above a beast: for all [is] vanity.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Create two reading cards for human and beast and mark the common phrase. Read the next two verses and note the question the passage asks.', 'Worked check — Ecclesiastes 3:19 says they all have one breath and both die; the surrounding verses continue asking about their fate. It does not reduce every use of breath and spirit to one doctrine. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-mind/biblical-reality-094/'),
  ('biblical-reality-094', 'kjv-mind', 200, '94. Numbers & Sacred Geometry', 'Make an evidence card for Numbers & Sacred Geometry. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Exodus 25; Revelation 21; Exodus 25:10; Revelation 21:16. Anchor verse (Exodus 25:10): “¶ And they shall make an ark [of] shittim wood: two cubits and a half [shall be] the length thereof, and a cubit and a half the breadth thereof, and a cubit and a half the height thereof.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Draw the ark footprint from Exodus 25:10 and the city''s equal length, breadth and height from Revelation 21:16. Label the units and genres.', 'Worked check — Exodus gives dimensions for an object to be made. Revelation gives measurements within a visionary scene. The texts provide dimensions in different settings. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-mind/biblical-reality-095/'),
  ('biblical-reality-095', 'kjv-mind', 201, '95. Playfulness & Childlike Wonder', 'Make an evidence card for Playfulness & Childlike Wonder. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Matthew 18:3; Matthew 18:3–4. Anchor verse (Matthew 18:3): “And said, Verily I say unto you, Except ye be converted, and become as little children, ye shall not enter into the kingdom of heaven.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Read Matthew 18:3–4 and underline the quality Jesus names in the second verse. Compare it with your first impression of the phrase little children.', 'Worked check — Verse 3 uses a comparison with little children and verse 4 names humbling oneself. Playfulness is this list''s proposed connection, not the word used in the passage. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-mind/biblical-reality-096/'),
  ('biblical-reality-096', 'kjv-mind', 202, '96. Solitude & Walking Alone in the Wilderness', 'Make an evidence card for Solitude & Walking Alone in the Wilderness. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Luke 5:16; Luke 5:15–16. Anchor verse (Luke 5:16): “¶ And he withdrew himself into the wilderness, and prayed.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Write a one-sentence sequence using the nearby report of crowds, the withdrawal, and prayer. Mark place and purpose from the verse.', 'Worked check — Luke 5:16 reports withdrawal into the wilderness and prayer after the report spreads. Treat your own solitude example as an application. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-mind/biblical-reality-097/'),
  ('biblical-reality-097', 'kjv-mind', 203, '97. Writing & Keeping Personal Journals', 'Make an evidence card for Writing & Keeping Personal Journals. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Habakkuk 2:2. Anchor verse (Habakkuk 2:2): “And the LORD answered me, and said, Write the vision, and make [it] plain upon tables, that he may run that readeth it.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Design a brief, legible vision record as a paper exercise. Name the command, the thing written and the stated purpose in the verse.', 'Worked check — Habakkuk is told to write the vision and make it plain on tables. A personal journal is the exercise''s application of that written record. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-mind/biblical-reality-098/'),
  ('biblical-reality-098', 'kjv-mind', 204, '98. Humor & Sarcasm', 'Make an evidence card for Humor & Sarcasm. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — 1 Kings 18:27. Anchor verse (1 Kings 18:27): “And it came to pass at noon, that Elijah mocked them, and said, Cry aloud: for he [is] a god; either he is talking, or he is pursuing, or he is in a journey, [or] peradventure he sleepeth, and must be awaked.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Read Elijah''s words aloud as dialogue. Underline which possibilities he names and describe the tone using a word from the narrator.', 'Worked check — The KJV says Elijah mocked them. Identify the specific speech in the Baal narrative before drawing a general rule about humor. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-mind/biblical-reality-099/'),
  ('biblical-reality-099', 'kjv-mind', 205, '99. Forgiving Without Ritual', 'Make an evidence card for Forgiving Without Ritual. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Luke 23:43; Luke 23:42–43. Anchor verse (Luke 23:43): “And Jesus said unto him, Verily I say unto thee, To day shalt thou be with me in paradise.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Copy the request and Jesus'' reply in Luke 23:42–43. Mark what each speaker asks or promises and what action the scene reports.', 'Worked check — The man asks to be remembered and Jesus promises paradise. The scene narrates a response and names no added ceremony. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-mind/biblical-reality-100/'),
  ('biblical-reality-100', 'kjv-mind', 206, '100. Mercy Over Sacrifice', 'Make an evidence card for Mercy Over Sacrifice. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Hosea 6:6; Matthew 9:13; Matthew 9:10–13. Anchor verse (Hosea 6:6): “For I desired mercy, and not sacrifice; and the knowledge of God more than burnt offerings.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Read Hosea and Matthew aloud. Make one column for Hosea''s wording and one for the situation in which Jesus quotes it.', 'Worked check — Hosea sets mercy beside sacrifice and knowledge of God beside burnt offerings. Matthew applies the mercy quotation in a dispute about eating with publicans and sinners. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-mind/biblical-reality-101/'),
  ('biblical-reality-101', 'kjv-mind', 207, '101. The Kingdom Within', 'Make an evidence card for The Kingdom Within. Cite the exact words that support your reading and name the claim still to be checked.', 'KJV reading — Luke 17:21; Luke 17:20–21. Anchor verse (Luke 17:21): “Neither shall they say, Lo here! or, lo there! for, behold, the kingdom of God is within you.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Copy the KJV phrase and identify the audience in Luke 17:20. Compare the nearby statements about observation and location before proposing an interpretation.', 'Worked check — The KJV reads the kingdom of God is within you. Jesus is answering Pharisees who ask when it should come. A reading about inward experience is an interpretation to defend in context. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-expansion/')
INSERT INTO academy_way_missions
  (slug, path, position, title, outcome, build, flip, integrate, verify, link)
VALUES
  ('kjv-extension-01', 'kjv-expansion', 208, 'Let Your Yes Be Yes', 'Complete the exercise and defend a reading using the exact KJV wording.', 'KJV reading — Matthew 5:33–37; James 5:12. Anchor verse (Matthew 5:37): “But let your communication be, Yea, yea; Nay, nay: for whatsoever is more than these cometh of evil.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Write two answers to the same direct question, one with an oath attached and one with plain affirmation. Underline what the passages ask speakers to use.', 'Worked check — Both passages give yea and nay language in the context of oath-taking. State what you can affirm and identify what you still need to check. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/language/gaslighting-and-plain-truth/'),
  ('kjv-extension-02', 'kjv-expansion', 209, 'Calling Evil Good and Good Evil', 'Complete the exercise and defend a reading using the exact KJV wording.', 'KJV reading — Isaiah 5:20–23. Anchor verse (Isaiah 5:20): “¶ Woe unto them that call evil good, and good evil; that put darkness for light, and light for darkness; that put bitter for sweet, and sweet for bitter!” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Make a two-column table of the reversals in verse 20. Read verses 22–23 to connect the language with the conduct the passage names.', 'Worked check — The verse pairs good and evil, light and darkness, and bitter and sweet. The surrounding passage includes a warning about justifying the wicked for reward. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/humanities/truth-vs-the-made-up-truth/'),
  ('kjv-extension-03', 'kjv-expansion', 210, 'Hear the Other Side of the Record', 'Complete the exercise and defend a reading using the exact KJV wording.', 'KJV reading — Proverbs 18:13; Proverbs 18:17. Anchor verse (Proverbs 18:13): “He that answereth a matter before he heareth [it], it [is] folly and shame unto him.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Write a one-line answer after reading one side of a fictional dispute. Read a second account, then revise the answer and mark what changed.', 'Worked check — One proverb addresses answering before hearing; the other shows why the first account must face examination. The later account also needs evidence. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/language/read-back-the-exact-words/'),
  ('kjv-extension-04', 'kjv-expansion', 211, 'Witnesses and False Accusations', 'Complete the exercise and defend a reading using the exact KJV wording.', 'KJV reading — Deuteronomy 19:15–21. Anchor verse (Deuteronomy 19:15): “¶ One witness shall not rise up against a man for any iniquity, or for any sin, in any sin that he sinneth: at the mouth of two witnesses, or at the mouth of three witnesses, shall the matter be established.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Make a diagram for the number of witnesses, what happens after a disputed charge, and who conducts the inquiry. Use a fictional dispute for practice.', 'Worked check — The passage requires more than a single witness in its legal setting and calls for diligent inquiry into a false-witness charge. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/life/correct-the-record-without-erasing-it/'),
  ('kjv-extension-05', 'kjv-expansion', 212, 'Prove the Claim Before Passing It On', 'Complete the exercise and defend a reading using the exact KJV wording.', 'KJV reading — Acts 17:10–12; 1 Thessalonians 5:21. Anchor verse (Acts 17:11): “These were more noble than those in Thessalonica, in that they received the word with all readiness of mind, and searched the scriptures daily, whether those things were so.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Record what the Bereans did after hearing the message. Practice on a short quotation and check the actual paragraph before deciding how it is being used.', 'Worked check — Acts says the Bereans received the word and searched the scriptures daily to check it. Thessalonians says to prove all things and hold fast the good. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/life/check-before-sharing/'),
  ('kjv-extension-06', 'kjv-expansion', 213, 'Try the Spirits', 'Complete the exercise and defend a reading using the exact KJV wording.', 'KJV reading — 1 John 4:1–3. Anchor verse (1 John 4:1): “Beloved, believe not every spirit, but try the spirits whether they are of God: because many false prophets are gone out into the world.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Mark the instruction, its stated reason, and the specific test in the next two verses. Keep a historical text claim apart from a modern case.', 'Worked check — Verse 1 gives the instruction to try the spirits because many false prophets are gone out. The next verses give the letter''s stated confession test. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-dreams/biblical-reality-055/'),
  ('kjv-extension-07', 'kjv-expansion', 214, 'What Isaiah Means in the Peace and Evil Pair', 'Complete the exercise and defend a reading using the exact KJV wording.', 'KJV reading — Isaiah 45:1–7; Isaiah 45:8. Anchor verse (Isaiah 45:7): “I form the light, and create darkness: I make peace, and create evil: I the LORD do all these [things].” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Copy every opposition in verse 7 in order. Read from verse 1 and identify the named ruler and how the passage frames events. Defend a possible sense of evil from its pairing with peace.', 'Worked check — The KJV prints evil opposite peace in an oracle naming Cyrus. Adversity or calamity is a contextual reading to explain; preserve the KJV word in the quotation. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-nature/biblical-reality-008/'),
  ('kjv-extension-08', 'kjv-expansion', 215, 'Read the God of This World in Context', 'Complete the exercise and defend a reading using the exact KJV wording.', 'KJV reading — 2 Corinthians 4:3–6; Ephesians 2:2. Anchor verse (2 Corinthians 4:4): “In whom the god of this world hath blinded the minds of them which believe not, lest the light of the glorious gospel of Christ, who is the image of God, should shine unto them.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Read verses 4 and 6 next to each other. Identify blinding and shining as separate actions in the argument. Record where the title occurs.', 'Worked check — Second Corinthians 4:4 uses the god of this world in connection with blinded minds. Verse 6 speaks of God giving light. A broader doctrinal identification needs to be argued from context and cross-references. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-mind/biblical-reality-101/'),
  ('kjv-extension-09', 'kjv-expansion', 216, 'Hear, Speak, and Do', 'Complete the exercise and defend a reading using the exact KJV wording.', 'KJV reading — James 1:19–25. Anchor verse (James 1:19): “Wherefore, my beloved brethren, let every man be swift to hear, slow to speak, slow to wrath:” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Mark three directions in verse 19 and draw the mirror example from verses 23–24. Test one example in which a person heard but did nothing.', 'Worked check — The passage says swift to hear, slow to speak, slow to wrath, and later asks readers to be doers. The mirror illustrates the person who hears and forgets. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/language/read-back-the-exact-words/'),
  ('kjv-extension-10', 'kjv-expansion', 217, 'Bring Hidden Works to Light', 'Complete the exercise and defend a reading using the exact KJV wording.', 'KJV reading — Ephesians 5:8–14. Anchor verse (Ephesians 5:11): “And have no fellowship with the unfruitful works of darkness, but rather reprove [them].” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Draw a line between what the passage asks readers to do and modern decisions about how to report something. For a fictional case, mark what was observed and what is hearsay.', 'Worked check — The passage asks readers to reprove unfruitful works of darkness. An account that someone can check distinguishes what the reporter observed from what was told to them. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/life/correct-the-record-without-erasing-it/'),
  ('kjv-extension-11', 'kjv-expansion', 218, 'Teach Through the Day', 'Complete the exercise and defend a reading using the exact KJV wording.', 'KJV reading — Deuteronomy 6:4–9; Psalm 78:3–7. Anchor verse (Deuteronomy 6:7): “And thou shalt teach them diligently unto thy children, and shalt talk of them when thou sittest in thine house, and when thou walkest by the way, and when thou liest down, and when thou risest up.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'List where and when Deuteronomy places the teaching. Design a short read-aloud and an exact retelling for one of those settings.', 'Worked check — The passage names sitting at home, walking, lying down and rising. Psalm 78 names passing knowledge to the next generation. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-remembrance/biblical-reality-075/'),
  ('kjv-extension-12', 'kjv-expansion', 219, 'Care for the Fatherless and Widows', 'Complete the exercise and defend a reading using the exact KJV wording.', 'KJV reading — James 1:26–27; Matthew 25:35–40. Anchor verse (James 1:27): “Pure religion and undefiled before God and the Father is this, To visit the fatherless and widows in their affliction, [and] to keep himself unspotted from the world.” Read the surrounding verses before beginning.', 'Underline the exact words that bear on the heading. Mark each key line as a reported event, an instruction, a figure of speech, or a question. Circle any wording supplied by the heading.', 'Mark the specific people named in James and the actions named in Matthew. Plan one fictional service response and name how you would keep it accountable.', 'Worked check — James describes visiting the fatherless and widows in affliction and keeping oneself unspotted. Matthew names actions including feeding and visiting. Your plan is an application. Point to the KJV verse that supports your answer and state one limit on what you can conclude.', 'way/kjv-mind/biblical-reality-100/')
